use std::path::Path;
use sysmlv2_model::{model::{Model, GraphFormat}, json::{Derived, ResolvedModel}};
fn library(model: &mut Model, path: &Path) {
    let mut entries: Vec<_> = std::fs::read_dir(path).unwrap().map(|e| e.unwrap().path()).collect();
    entries.sort();
    for entry in entries {
        if entry.is_dir() { library(model, &entry); }
        else if matches!(entry.extension().and_then(|x|x.to_str()), Some("sysml"|"kerml")) {
            model.add_library_source(entry.to_string_lossy(), &std::fs::read_to_string(&entry).unwrap());
        }
    }
}
fn main() { std::thread::Builder::new().stack_size(16*1024*1024).spawn(|| {
 let mut model=Model::with_graph_format(GraphFormat::CanonicalV3);
 library(&mut model,Path::new("vendor/sysml-library/sources"));
 model.add_source("triggers.sysml",&std::fs::read_to_string("tests/conformance/fixtures/trigger-arguments-positive.sysml").unwrap());
 let mut r=ResolvedModel::build(&model);
 r.set_closure_policy(sysmlv2_model::json::ClosurePolicy::Closure{include_implied:true});
 let package=r.resolve_qualified("TriggerArguments").unwrap();r.implied_relationships(package);
 for name in ["conditional","literal"] {
  let accept=r.resolve_qualified(&format!("TriggerArguments::Reception::{name}")).unwrap();
  let Derived::Value(v)=r.derived(accept,"payloadArgument") else{panic!()};let trigger=v.element().unwrap();
  let bindings=r.invocation_binding_report(trigger).arguments.unwrap();
  let outer=bindings.bindings[0].value;
  let Derived::Value(v)=r.derived(outer,"referent") else{panic!()};let inner=v.element().unwrap();
  let Derived::Value(v)=r.derived(inner,"result") else{panic!()};let result=v.element().unwrap();
  let singular=r.resolve_qualified("Performances::Performance::enclosedPerformance");
  let enclosed=r.resolve_qualified("Performances::Performance::enclosedPerformances").unwrap();
  let result_owner=r.owner(result).unwrap();
  println!("{name}: result owner kind={}, singular target present={}, plural target specialization={}",r.element_type(result_owner),singular.is_some(),r.conforms_with_implied(inner,enclosed));
  println!("{name}: outer={} inner={} inner owner={:?} result_owner={:?} domain={:?}",r.element_type(outer),r.element_type(inner),r.owner(inner),r.owner(result),r.type_feature_report(result));
 }
 }).unwrap().join().unwrap();}

